mapper.select:
SELECT t3.`id`, t3.`code`, t3.`name`, t3.`icon`, t3.`remark`, t3.`enabled`, t3.`application_group_id`, t3.`create_time`, t3.`update_time` FROM ( SELECT t1.`application_code`, MAX(t1.`visit_time`) as `visit_time` FROM `application_visit_history` t1
t1.`user_id` = #{userId} AND t1.`terminal` = #{terminal}
GROUP BY t1.`application_code` ) t2 INNER JOIN `application` t3 ON t2.`application_code` = t3.`code`
AND t3.`id` IN
#{id}
ORDER BY t2.`visit_time` DESC

SELECT t2.`application_code`, t2.`visit_time` FROM ( SELECT t1.`application_code`, MAX(t1.`visit_time`) as `visit_time` FROM `application_visit_history` t1
t1.`user_id` = #{userId} AND t1.`terminal` = #{terminal}
GROUP BY t1.`application_code` ) t2 INNER JOIN `application` t3 ON t2.`application_code` = t3.`code`
AND t3.`id` IN
#{id}
ORDER BY t2.`visit_time` DESC
